def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    last_me, last_opp = history[-1]
    if last_opp == 'C':
        return 'C'
    if n < 90:
        if n >= 2 and last_me == 'C' and history[-2][0] == 'D' and history[-2][1] == 'C':
            return 'C'
        if n >= 3 and last_me == 'D' and history[-2][0] == 'D' and history[-3][0] == 'D' and history[-2][1] == 'D' and history[-3][1] == 'D':
            opp_c = sum(1 for h in history if h[1] == 'C')
            if opp_c > n / 2:
                return 'C'
    return 'D'
